// augur-contract-runtime version=2 sha256=8bac8014c83e3fb1d757f2840c56f0dc0ea86e5634bc0361f2099e5d82429b7b
// Generated by `augur contracts runtime sync` from Augur templates/contract-runtime. Edit the template, then re-sync.
// Augur `contract-wrap` runtime for C++ (C++17, header-only).
//
// The C++ twin of contract-runtime.ts: the same verdict rules and the same
// weaver JSONL, so `augur contracts report` reads C++ observations exactly like
// TypeScript ones. The wrapped function's result and exceptions pass through
// untouched; only the verdict is appended to `contracts.jsonl` under
// `VESTIGIUM_LOGS_DIR` (or `<cwd>/logs`). Arguments and results are never
// recorded — they may carry credentials.
//
// Daily rotation: the active file holds the current day only. On the first
// write of a new day the previous file moves to
// `archive/contracts-YYYY-MM-DD.jsonl`, which `augur contracts report` never
// reads, and archives older than the retention window
// (`AUGUR_CONTRACT_LOG_RETENTION_DAYS`, default 7) are deleted. The day
// boundary is JST (UTC+9, no DST).
//
// Usage:
//   auto checked = augur::contract(
//       [](int value) { return value * 2; },
//       augur::ContractSpec{"C-1", "3b738b4c", "src/math.cpp:12"},
//       [](int value) { return value >= 0 ? augur::pass() : augur::fail("negative input"); },
//       [](int result, int) -> augur::Verdict { return result >= 0 ? augur::pass() : augur::fail("negative"); });
//
// A predicate returns `augur::Verdict` (pass() / fail(reason)), `bool`
// (false = "predicate failed"), or a string (the violation reason; an empty
// string counts as no violation, as in the TypeScript runtime). `pre` receives
// the arguments; `post` receives the result followed by the arguments, or only
// the arguments when the function returns void. Arguments are handed to the
// function as lvalues, so `post` reads the same values `pre` saw.
//
// Not covered (the TypeScript runtime awaits promises): a returned
// std::future is judged as a value when the call returns, not when it resolves.
//
// @implements SPEC-CONTRACT-RUNTIME-TEMPLATE
#pragma once

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <map>
#include <mutex>
#include <optional>
#include <regex>
#include <string>
#include <system_error>
#include <type_traits>
